export function buildUnifiedReviews({calendar=[],reviewAgenda=[],subjectIdOf=()=>null,subjectName=()=>'',topicName=()=>''}={}){
  const calendarItems=calendar.map(i=>({
    id:i.id,date:i.date,subjectId:subjectIdOf(i),subject:subjectName(i),
    label:i.reviewType&&i.reviewType!=='—'?i.reviewType:'Revisão',
    status:i.status||'Não iniciado',origem:'Calendário'
  }));
  const agendaItems=reviewAgenda.map(i=>({
    id:i.id,date:i.date,subjectId:subjectIdOf(i),subject:subjectName(i),
    label:`${i.topicId?topicName(i.topicId):(i.topic||'Tópico')} · ${i.tipo||''}`,
    status:i.status||'Não iniciado',origem:'Agenda de Revisões'
  }));
  return [...calendarItems,...agendaItems];
}
